    char *buffer;
    size_t buffer_size = 1024;
    buffer = (char *)malloc(buffer_size);
    if (!buffer) return 1;

    while (fgets(line, sizeof(line), stdin)) {
        word = strtok(line, " \t\n");
        while (word) {
            words++;
            // Check for distinct words
            char *p = buffer;
            size_t len = strlen(word);
            bool found = false;
            while (*p != '\0') {
                if (strncmp(p, word, len) == 0 && (p[len] == '\0' || p[len] == ' ')) {
                    found = true;
                    break;
                }
                while (*p != '\0') p++;
                p++; // Skip the space
            }
            if (!found) {
                if ((size_t)(p - buffer + len + 1) > buffer_size) {
                    buffer_size *= 2;
                    char *new_buffer = (char *)realloc(buffer, buffer_size);
                    if (!new_buffer) return 1;
                    buffer = new_buffer;
                }
                memcpy(p, word, len);
                p += len;
                *p++ = ' ';
                distinct_words++;
            }
            word = strtok(NULL, " \t\n");
        }
    }

    printf("words=%d distinct=%d\n", words, distinct_words);

    free(buffer);
    return 0;
